use vstd::prelude::*;

verus! {
    // Specification of "odd": an integer whose remainder mod 2 is nonzero.
    spec fn is_odd(x: int) -> bool {
        x % 2 != 0
    }

    // Finds the first odd element in the array, if any.
    // Returns (found, index).
    //   - If found == true, then
    //       index < a.len(),
    //       a[index] is odd,
    //       and for all j < index, a[j] is even.
    //   - If found == false, then
    //       for all j < a.len(), a[j] is even.
    fn find_first_odd(a: &[i32]) -> (found: bool, index: usize)
        ensures
            if found {
                index < a.len()
                && is_odd(a[index] as int)
                && forall(|j: usize| j < index ==> !is_odd(a[j] as int))
            } else {
                forall(|j: usize| j < a.len() ==> !is_odd(a[j] as int))
            }
    {
        let len = a.len();
        let mut i: usize = 0;
        // Loop invariant: for all j < i, a[j] is even.
        while i < len
            invariant
                forall(|j: usize| j < i ==> !is_odd(a[j] as int)),
            decreases
                len - i
        {
            if is_odd(a[i] as int) {
                return (true, i);
            }
            i = i + 1;
        }
        // No odd found
        return (false, 0);
    }
}

